# Sourced by startplasma before KWin and the shell start: the UI font for the
# session's language (Figtree, or Inter for languages Figtree has no letters
# for: Russian, Greek, ...). See /usr/lib/lucent/lucent_theme/fonts.py.
[ -x /usr/bin/lucent-theme ] && /usr/bin/lucent-theme font --apply >/dev/null 2>&1 || true
